intro p q r hqr hrq;
obtain ⟨μ, hμ⟩ := ProbabilityTheory.isFiniteKernel.exists_finite_measure κ;
let μ' := μ.restrict (Set.Iic ↑q);
have hμ' : ProbabilityTheory.IsFiniteMeasure μ' := by apply μ'.is_finite;
let f := fun x => κ.density κ.fst x.1 x.2 (Set.Iic ↑q);
have hf : MeasurableFunction f := by apply ProbabilityTheory.isFiniteKernel.measurable_density κ;
let g := fun x => κ.density κ.fst x.1 x.2 (Set.Iic ↑r);
have hg : MeasurableFunction g := by apply ProbabilityTheory.isFiniteKernel.measurable_density κ;
let h₁ := ProbabilityTheory.measurableFunction.integral_mono hf hg (fun x => Set.Iic ↑q ⊆ Set.Iic ↑r) (fun x => Set.Iic ↑r ⊆ Set.Iic ↑q) hqr hrq;
let h₂ := ProbabilityTheory.measurableFunction.integral_mono hf hg (fun x => Set.Iic ↑r ⊆ Set.Iic ↑q) (fun x => Set.Iic ↑q ⊆ Set.Iic ↑r) hrq hqr;
have h₃ := ProbabilityTheory.isFiniteKernel.is_rat_cond_kernel_cdf_helper κ μ' f g h₁ h₂;
apply h₃;
